examples.template:
if isOptOutRegion {
    Button {
        draft = allowsSale && !isLockedBySignal
        isOpen = true
    } label: {
        Text({{label}}).underline()
    }
    .buttonStyle(.monarchLink(.standalone))
    .monarchTextStyle(.label)
    .sheet(isPresented: $isOpen) {
        NavigationStack {
            Form {
                Section {
                    Text("We may share information about how you use the app, such as screens viewed and device identifiers, with advertising partners. You can turn this off at any time.")
                        .monarchTextStyle(.body)
                }
                Section {
                    Toggle("Allow sale or sharing", isOn: $draft)
                        .disabled(isLockedBySignal)
                } footer: {
                    Text(
                        isLockedBySignal
                            ? "A Global Privacy Control signal is on for your account, so sale and sharing stay off."
                            : "When off, we stop selling or sharing your personal information."
                    )
                }
                if let policy = URL(string: "https://example.com/privacy") {
                    Link("Privacy policy", destination: policy)
                        .buttonStyle(.monarchLink(.standalone, isExternal: true))
                }
            }
            .navigationTitle({{label}})
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { isOpen = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        // Store the choice for the sale and sharing consent categories.
                        allowsSale = draft
                        isOpen = false
                    }
                }
            }
        }
        .presentationDetents([.medium, .large])
    }
}

examples.setupTemplate:
@State private var isOpen = false
@State private var allowsSale = true
@State private var draft = true
/// Whether the person lives where they may opt out of sale or sharing. The app decides.
private let isOptOutRegion = true
/// Whether the account carries a Global Privacy Control opt-out, for example from the website.
private let isLockedBySignal = false

